package com.portfolio.agent.answer.synthesis.codec;
import com.fasterxml.jackson.core.JsonParser; import com.fasterxml.jackson.databind.JsonNode; import com.fasterxml.jackson.databind.ObjectMapper; import java.util.Iterator; import java.util.Map; import java.util.Set;
public final class CrossDomainDraftCodec { private final ObjectMapper mapper=new ObjectMapper().enable(JsonParser.Feature.STRICT_DUPLICATE_DETECTION); public Draft decode(String raw){try{JsonNode n=mapper.readTree(raw);allowed(n,"schemaVersion","sectionKind","text","relationAlias","statementAliases","caveatAliases");if(!"cross-domain-expression-v1".equals(text(n,"schemaVersion")))fail();String text=text(n,"text");if(text.length()>2400)fail();String relation=text(n,"relationAlias");return new Draft(text,relation,textArray(n,"statementAliases"),textArray(n,"caveatAliases"));}catch(CrossDomainDraftException e){throw e;}catch(Exception e){throw new CrossDomainDraftException();}} private String[] textArray(JsonNode n,String f){JsonNode a=n.get(f);if(!a.isArray()||a.size()>8)fail();String[] r=new String[a.size()];for(int i=0;i<a.size();i++)r[i]=a.get(i).isTextual()?a.get(i).asText():bad();return r;} private String text(JsonNode n,String f){if(!n.has(f)||!n.get(f).isTextual()||n.get(f).asText().isBlank())fail();return n.get(f).asText();} private static void allowed(JsonNode n,String...fs){if(n==null||!n.isObject())fail();Set<String>s=Set.of(fs);Iterator<Map.Entry<String,JsonNode>>i=n.fields();while(i.hasNext())if(!s.contains(i.next().getKey()))fail();for(String f:fs)if(!n.has(f))fail();} private static void fail(){throw new CrossDomainDraftException();} private static String bad(){fail();return null;}
    public static final class Draft { private final String text; private final String relationAlias; private final String[] statementAliases; private final String[] caveatAliases; public Draft(String text,String relationAlias,String[] statementAliases,String[] caveatAliases){this.text=text;this.relationAlias=relationAlias;this.statementAliases=statementAliases.clone();this.caveatAliases=caveatAliases.clone();} public String getText(){return text;} public String getRelationAlias(){return relationAlias;} public java.util.List<String> getStatementAliases(){return java.util.List.of(statementAliases);} public java.util.List<String> getCaveatAliases(){return java.util.List.of(caveatAliases);} }
}
